namespace {
struct Series {QString label;QVector<double> values;QColor color;};
struct Chart {QString title,unit,source,note,mode="bars";QStringList labels;QVector<Series> series;QJsonObject field;};
const double missing=std::numeric_limits<double>::quiet_NaN();
QString bilingual(bool en,const char *vi,const char *english){return QString::fromUtf8(en?english:vi);}
class ChartCanvas:public QWidget {
public:
 Chart chart;ga::Project project;bool english=false;bool dark=false;
 ChartCanvas(QWidget *parent=nullptr):QWidget(parent){setMinimumSize(520,430);setAccessibleName("Native analysis chart");}
 void paint(QPainter &p,const QRectF &page,bool forPrint=false) const {
  const bool useDark=dark&&!forPrint;
  p.save();p.translate(page.topLeft());p.setRenderHint(QPainter::Antialiasing);const double w=page.width(),h=page.height();
  p.fillRect(QRectF(0,0,w,h),useDark?QColor("#171615"):QColor("#fcfcf8"));
  p.setPen(useDark?QColor("#f2efe9"):QColor("#364538"));p.setFont(QFont("Segoe UI",17,QFont::DemiBold));p.drawText(QRectF(30,24,w-60,58),Qt::TextWordWrap,chart.title);
  p.setFont(QFont("Segoe UI",9));p.setPen(useDark?QColor("#a8a29a"):QColor("#7a8475"));p.drawText(QRectF(30,86,w-60,35),Qt::TextWordWrap,chart.unit);const QRectF plot(64,142,w-105,h-290);
  if(chart.mode=="grid")drawGrid(p,plot,useDark);
  else if(chart.series.isEmpty()){p.drawText(plot,Qt::AlignCenter|Qt::TextWordWrap,chart.note);}
  else if(chart.mode=="rose")drawRose(p,plot,useDark);
  else drawCartesian(p,plot,useDark);
  p.setFont(QFont("Segoe UI",8));p.setPen(useDark?QColor("#a8a29a"):QColor("#667261"));p.drawText(QRectF(30,h-122,w-60,52),Qt::TextWordWrap,chart.source);
  p.setPen(useDark?QColor("#827c74"):QColor("#8a8e80"));p.drawText(QRectF(30,h-65,w-60,55),Qt::TextWordWrap,chart.note);p.restore();
 }
protected:
 void paintEvent(QPaintEvent *)override{QPainter p(this);paint(p,rect(),false);}
private:
 void drawCartesian(QPainter &p,const QRectF &plot,bool useDark)const{
  double low=0,high=0;for(const auto &s:chart.series)for(double v:s.values)if(std::isfinite(v)){low=std::min(low,v);high=std::max(high,v);}if(high==low)high=low+1;const double padding=(high-low)*.08;high+=padding;if(low<0)low-=padding;
  const QColor gridC=useDark?QColor("#2c2a27"):QColor("#e4e7dc"),lblC=useDark?QColor("#b8b1a8"):QColor("#6c7866"),tickC=useDark?QColor("#9a948c"):QColor("#828d7c");
  const auto y=[&](double value){return plot.bottom()-(value-low)/(high-low)*plot.height();};p.setFont(QFont("Segoe UI",8));for(int i=0;i<=4;++i){const double value=low+(high-low)*i/4,yy=y(value);p.setPen(QPen(gridC,1));p.drawLine(QPointF(plot.left(),yy),QPointF(plot.right(),yy));p.setPen(tickC);p.drawText(QRectF(0,yy-9,plot.left()-10,18),Qt::AlignRight|Qt::AlignVCenter,QString::number(value,'g',3));}
  const int count=chart.labels.size();if(count<1)return;const double slot=plot.width()/count;const auto x=[&](int i){return plot.left()+(i+.5)*slot;};for(int i=0;i<count;++i){p.setPen(lblC);p.save();p.translate(x(i),plot.bottom()+12);if(count>12||chart.labels[i].size()>9){p.rotate(-35);p.drawText(QRectF(-65,0,75,36),Qt::AlignRight|Qt::TextWordWrap,chart.labels[i]);}else p.drawText(QRectF(-slot/2,0,slot,32),Qt::AlignCenter|Qt::TextWordWrap,chart.labels[i]);p.restore();}
  for(int j=0;j<chart.series.size();++j){const auto &s=chart.series[j];p.setPen(QPen(s.color,2));p.setBrush(s.color);QPainterPath line;bool started=false;for(int i=0;i<std::min(count,int(s.values.size()));++i){const double v=s.values[i];if(!std::isfinite(v)){started=false;continue;}if(chart.mode=="line"){const QPointF q(x(i),y(v));if(started)line.lineTo(q);else line.moveTo(q);started=true;p.drawEllipse(q,2.5,2.5);}else{const double bw=slot*.7/chart.series.size(),xx=x(i)-slot*.35+j*bw;p.drawRoundedRect(QRectF(xx,std::min(y(v),y(0)),std::max(1.,bw-2),std::abs(y(v)-y(0))),2,2);}}if(chart.mode=="line"){p.setBrush(Qt::NoBrush);p.drawPath(line);}}
  double xx=plot.left();for(const auto &s:chart.series){p.setPen(Qt::NoPen);p.setBrush(s.color);p.drawEllipse(QPointF(xx,plot.top()-23),4,4);p.setPen(lblC);p.drawText(xx+10,plot.top()-19,s.label);xx+=p.fontMetrics().horizontalAdvance(s.label)+35;}
 }
 void drawRose(QPainter &p,const QRectF &plot,bool useDark)const{
  const auto &s=chart.series.first();double maximum=1;for(const double v:s.values)if(std::isfinite(v))maximum=std::max(maximum,v);maximum=std::ceil(maximum/5)*5;const double radius=std::min(plot.width(),plot.height())*.43;const auto center=plot.center();p.setFont(QFont("Segoe UI",8));for(int i=1;i<=4;++i){const double r=radius*i/4;p.setPen(QPen(useDark?QColor("#34312d"):QColor("#dce2d3"),1));p.setBrush(Qt::NoBrush);p.drawEllipse(center,r,r);p.setPen(useDark?QColor("#9a948c"):QColor("#87927e"));p.drawText(center+QPointF(5,-r+12),QString::number(maximum*i/4,'g',3)+"%");}
  for(int i=0;i<16&&i<s.values.size();++i){if(!std::isfinite(s.values[i]))continue;const double angle=i*M_PI/8-M_PI/2,r=radius*s.values[i]/maximum;QPolygonF wedge{center};for(int k=0;k<=6;++k){const double a=angle-.13+k*.26/6;wedge.append(center+QPointF(std::cos(a),std::sin(a))*r);}p.setPen(QPen(QColor("#3c6859"),.6));p.setBrush(ga::rampColor(double(i)/16));p.drawPolygon(wedge);if(i%2==0){p.setPen(useDark?QColor("#d4cec4"):QColor("#506347"));p.drawText(QRectF(center+QPointF(std::cos(angle),std::sin(angle))*(radius+22)-QPointF(26,10),QSizeF(52,20)),Qt::AlignCenter,chart.labels.value(i));}}
 }
 void drawGrid(QPainter &p,const QRectF &plot,bool useDark)const{
  const auto image=ga::gridImage(chart.field);const auto bbox=chart.field["bbox"].toArray();if(image.isNull()||bbox.size()!=4){p.drawText(plot,Qt::AlignCenter,english?"No valid grid data":"Không có lưới dữ liệu hợp lệ");return;}
  const auto sw=ga::localPoint(bbox[0].toDouble(),bbox[1].toDouble(),project.site),ne=ga::localPoint(bbox[2].toDouble(),bbox[3].toDouble(),project.site);const QRectF extent(QPointF(sw.x(),-ne.y()),QPointF(ne.x(),-sw.y()));const double scale=std::min(plot.width()/extent.width(),plot.height()/extent.height());QTransform t;t.translate(plot.center().x(),plot.center().y());t.scale(scale,scale);t.translate(-extent.center().x(),-extent.center().y());p.save();p.setClipRect(plot);const auto target=t.mapRect(extent);p.fillRect(target,useDark?QColor("#24221f"):QColor("#e8e9e0"));p.drawImage(target,image);
  p.setBrush(Qt::NoBrush);p.setPen(QPen(QColor(30,45,35,120),.5));for(const auto &f:project.features)if(f.building()){QPainterPath shape;shape.setFillRule(Qt::OddEvenFill);for(const auto &ring:f.rings){QPolygonF poly;for(const auto &q:ring)poly.append(t.map(QPointF(q.x(),-q.y())));shape.addPolygon(poly);shape.closeSubpath();}p.drawPath(shape);}QPolygonF boundary;for(const auto &q:project.site.boundary)boundary.append(t.map(QPointF(q.x(),-q.y())));p.setPen(QPen(Qt::white,3));p.drawPolygon(boundary);p.setPen(QPen(QColor("#3d5339"),1,Qt::DashLine));p.drawPolygon(boundary);p.restore();const auto stats=chart.field["statistics"].toObject();for(int i=0;i<120;++i){p.setPen(ga::rampColor(i/119.));const double x=plot.left()+i*plot.width()/120;p.drawLine(QPointF(x,plot.bottom()+12),QPointF(x+plot.width()/120+1,plot.bottom()+12));}p.setPen(useDark?QColor("#a8a29a"):QColor("#62715b"));p.drawText(plot.left(),plot.bottom()+34,QString::number(stats["min"].toDouble(),'g',4));p.drawText(QRectF(plot.right()-95,plot.bottom()+20,95,20),Qt::AlignRight,QString::number(stats["max"].toDouble(),'g',4));p.drawText(plot.right()-15,plot.top()+18,"N ↑");
 }
};
struct Workspace:QWidget {
 QVector<Chart> charts;ChartCanvas *canvas;QListWidget *list;QLabel *overview;bool english;ga::Project project;
 Workspace(const ga::Project &p,bool en,bool darkTheme,QWidget *parent):QWidget(parent),english(en),project(p){
  auto layout=new QVBoxLayout(this);layout->setContentsMargins(20,18,20,18);const auto tr=[&](const char *vi,const char *enText){return bilingual(en,vi,enText);};overview=new QLabel(this);overview->setWordWrap(true);auto stats=p.stats();overview->setText(p.site.name+"  ·  "+QString::number(stats.buildings)+tr(" công trình · "," buildings · ")+QString::number(stats.knownHeights)+tr(" có chiều cao"," with height values"));layout->addWidget(overview);auto row=new QHBoxLayout();layout->addLayout(row,1);list=new QListWidget(this);list->setObjectName("analysis-charts");list->setFixedWidth(205);row->addWidget(list);canvas=new ChartCanvas(this);canvas->english=en;canvas->dark=darkTheme;canvas->project=p;row->addWidget(canvas,1);
  const auto analysis=ga::buildingAnalysis(p);const auto source=p.source["attribution"].toString();const auto sourceNote=tr("Đếm theo mã nguồn duy nhất. Chiều cao thiếu được loại khỏi phân bố; chiều cao AI và suy từ số tầng là ước tính.","Counts use unique source IDs. Unknown heights are excluded from the distribution; AI and floor-derived heights are estimates.");
  Chart height;height.title=tr("Phân bố chiều cao công trình","Building height distribution");height.unit=tr("Số công trình theo khoảng chiều cao (m)","Buildings by height range (m)");height.labels={"<5","5–10","10–20","20–40","40–80","≥80"};height.source=source;height.note=sourceNote+"  "+QString::number(analysis["unknown_heights"].toInt())+tr(" chưa có chiều cao."," have no height values.");Series hs{tr("Công trình","Buildings"),{},QColor("#7a9773")};for(const auto &v:analysis["height_bins"].toArray())hs.values.append(v.toDouble());height.series={hs};charts.append(height);
  Chart use;use.title=tr("Công năng theo thuộc tính nguồn","Building use from source tags");use.unit=tr("Số công trình · giá trị building trong nguồn OSM/nguồn nhập","Buildings · recorded building tag");use.source=source;use.note=tr("yes / unknown chỉ cho biết công trình tồn tại, không xác nhận công năng. Không suy đoán công năng từ hình học.","yes / unknown indicates building existence, not a verified use. Uses are not inferred from geometry.");Series us{tr("Công trình","Buildings"),{},QColor("#b28b67")};QVector<QPair<int,QString>> counts;const auto uses=analysis["building_use"].toObject();for(auto it=uses.begin();it!=uses.end();++it)counts.append({it.value().toInt(),it.key()});std::sort(counts.begin(),counts.end(),[](const auto &a,const auto &b){return a.first>b.first;});for(int i=0;i<std::min(12,int(counts.size()));++i){use.labels.append(counts[i].second);us.values.append(counts[i].first);}use.series={us};charts.append(use);
  const auto station=ga::nearestClimate(ga::appDataPath("climate.json"),p.site),climate=station["climate"].toObject();
  if(!station.isEmpty()){
   const auto months=climate["monthly"].toArray();QStringList monthLabels;for(int i=1;i<=12;++i)monthLabels.append(QString::number(i));const auto stationSource=climate["source"].toString()+" · "+station["station"].toString()+" · "+QString::number(station["distance_km"].toDouble(),'f',1)+" km · TMYx "+climate["period"].toString()+"\n"+climate["url"].toString();const auto note=tr("Năm khí tượng điển hình (TMY), không phải thời tiết trực tiếp hay đo tại khu đất. Dữ liệu từ trạm trong phạm vi 100 km; giá trị thiếu không thay bằng 0.","Typical meteorological year (TMY), not live weather or a site measurement. Station within 100 km; missing values are not replaced with zero.");
   const auto monthly=[&](const char *vi,const char *english,const QString &unit,const QVector<QString> &keys,const QStringList &names,const QVector<QColor> &colors,const QString &mode){Chart c;c.title=tr(vi,english);c.unit=unit;c.source=stationSource;c.note=note;c.mode=mode;c.labels=monthLabels;for(int k=0;k<keys.size();++k){Series s{names[k],{},colors[k]};for(const auto &v:months){const auto x=v.toObject()[keys[k]];s.values.append(x.isDouble()?x.toDouble():missing);}c.series.append(s);}charts.append(c);};
   monthly("Nhiệt độ không khí theo tháng","Monthly air temperature","°C",{"dailyLow","temperature","dailyHigh"},{tr("Thấp TB ngày","Mean daily low"),tr("Trung bình","Mean"),tr("Cao TB ngày","Mean daily high")},{QColor("#77a4a0"),QColor("#bc825a"),QColor("#c46954")},"line");
   monthly("Độ ẩm tương đối","Relative humidity","% RH",{"humidity"},{tr("Độ ẩm","Humidity")},{QColor("#7ca5a0")},"bars");
   monthly("Tốc độ gió theo tháng","Monthly wind speed","m/s",{"windSpeed"},{tr("Gió tại trạm","Station wind")},{QColor("#8f9f78")},"bars");
   monthly("Bức xạ mặt trời theo tháng","Monthly solar irradiation","kWh/m²",{"ghi","dni","dhi"},{"GHI","DNI","DHI"},{QColor("#c78d57"),QColor("#a85d4b"),QColor("#a9ba88")},"line");
   auto roses=climate["seasons"].toArray();roses.prepend(QJsonObject{{"id",tr("Cả năm","Annual")},{"bins",climate["wind"].toObject()["bins"]},{"calmPercent",climate["wind"].toObject()["calmPercent"]}});for(const auto &v:roses){const auto rose=v.toObject();Chart c;c.title=tr("Hoa gió · ","Wind rose · ")+rose["id"].toString();c.unit=tr("Tần suất gió theo hướng gió đến · % số giờ gió hợp lệ","Wind-from direction frequency · % valid wind hours");c.mode="rose";c.source=stationSource;c.note=note+"  "+tr("Lặng gió: ","Calm: ")+QString::number(rose["calmPercent"].toDouble(),'f',1)+"%.";Series s{"",{},QColor("#719482")};for(const auto &bin:rose["bins"].toArray()){const auto b=bin.toObject();c.labels.append(b["direction"].toString());s.values.append(b["percent"].isDouble()?b["percent"].toDouble():missing);}c.series={s};charts.append(c);}
  }else{Chart c;c.title=tr("Khí hậu · chưa có trạm phù hợp","Climate · no matching station");c.note=tr("Chưa có trạm TMY đi kèm trong bán kính 100 km. Không nội suy dữ liệu Việt Nam sang vị trí khác.","No bundled TMY station within 100 km. Vietnam data is not extrapolated to other locations.");charts.append(c);}
  const auto fields=ga::environmentFields(ga::appDataPath("environment"),p.site);const QMap<QString,QStringList> names={{"landsat",{"Nhiệt độ bề mặt đất","Land surface temperature"}},{"sentinel",{"Chỉ số thực vật NDVI","Vegetation index NDVI"}},{"flood",{"Ngập sông · kịch bản RP100","River flood · RP100 scenario"}},{"canopy",{"Chiều cao tán cây","Canopy height"}},{"gedtm30",{"Cao độ địa hình","Terrain elevation"}},{"population",{"Dân số theo ô lưới","Population per grid cell"}}};
  for(const auto &field:fields){Chart c;c.field=field;c.mode="grid";c.title=names.value(field["id"].toString(),{field["id"].toString(),field["id"].toString()})[en?1:0];c.unit=field["units"].toString()+" · "+QString::number(field["width"].toInt())+" × "+QString::number(field["height"].toInt())+tr(" ô · Bắc ở trên"," cells · North up");c.source=field["source"].toString()+" · "+field["observed_at"].toString(field["loaded_at"].toString())+"\n"+field["license"].toString();c.note=(en?field["method"].toString():tr("Chỉ hiển thị cửa sổ dữ liệu nguồn đã lưu; ô thiếu để trong suốt. Đường nét công trình chỉ dùng để định vị. ",""))+tr(" Không phải dữ liệu trực tiếp."," Saved source window; nodata cells are transparent. Not live data.");if(field["id"].toString()=="flood")c.note=tr("Độ sâu ngập sông mô hình hóa cho kịch bản chu kỳ lặp 100 năm; không phải dự báo ngập hay xác nhận pháp lý khu đất.","Modeled river-flood depth for a 100-year return-period scenario; not a forecast or legal site assessment.");if(field["id"].toString()=="landsat")c.note+=tr(" Nhiệt độ bề mặt khác nhiệt độ không khí."," Surface temperature differs from air temperature.");charts.append(c);}
  if(fields.isEmpty()){Chart c;c.title=tr("Môi trường · ngoài cửa sổ dữ liệu","Environment · outside data coverage");c.note=tr("Bản desktop đi kèm các lưới nguồn ở Hoàn Kiếm và Hạ Long. Khu đất này chưa nằm trong phạm vi dữ liệu, nên không tạo lớp giả.","Bundled grids cover source windows at Hoan Kiem and Ha Long. No data window covers this site.");charts.append(c);}
  for(const auto &c:charts){list->addItem(c.title);}
  connect(list,&QListWidget::currentRowChanged,this,[this](int i){if(i>=0&&i<charts.size()){canvas->chart=charts[i];canvas->update();}});list->setCurrentRow(0);
  auto buttons=new QHBoxLayout();layout->addLayout(buttons);auto explanation=new QLabel(tr("Vẽ và xuất bằng Qt trên máy","Rendered and exported locally with Qt"),this);buttons->addWidget(explanation,1);for(const auto &kind:QStringList{"PNG","CSV","PDF"}){auto button=new QPushButton(tr("Xuất ","Export ")+kind,this);buttons->addWidget(button);connect(button,&QPushButton::clicked,this,[this,kind]{const auto file=QFileDialog::getSaveFileName(this,bilingual(english,"Xuất phân tích","Export analysis"),project.site.name+"-analysis."+kind.toLower(),kind+" (*."+kind.toLower()+")");if(file.isEmpty())return;bool ok=kind=="PNG"?png(file):kind=="CSV"?csv(file):pdf(file);if(!ok)QMessageBox::warning(this,"GroundAtlas",bilingual(english,"Không ghi được tệp xuất.","Could not write the export file."));});}
 }
 bool png(const QString &file){QImage image(1500,1080,QImage::Format_RGB32);QPainter p(&image);canvas->paint(p,QRectF(0,0,1500,1080),true);p.end();return image.save(file,"PNG");}
 bool pdf(const QString &file){QSaveFile output(file);if(!output.open(QIODevice::WriteOnly))return false;bool ok=false;{QPdfWriter writer(&output);writer.setTitle(project.site.name+" · GroundAtlas analysis");writer.setCreator("GroundAtlas Desktop 2.2.0 / native Qt");writer.setPageSize(QPageSize(QPageSize::A4));writer.setResolution(120);QPainter painter(&writer);ok=painter.isActive();const auto original=canvas->chart;for(int i=0;ok&&i<charts.size();++i){if(i>0)ok=writer.newPage();canvas->chart=charts[i];canvas->paint(painter,QRectF(0,0,writer.width(),writer.height()),true);}canvas->chart=original;painter.end();}return ok&&output.commit();}
 bool csv(const QString &file){QSaveFile out(file);if(!out.open(QIODevice::WriteOnly))return false;QTextStream stream(&out);stream<<QChar(0xfeff);const auto quote=[](QString s){if(!s.isEmpty()&&QString("=+-@").contains(s[0]))s.prepend('\'');return '"'+s.replace('"',"\"\"")+'"';};stream<<"chart,series,label,value,unit,source,note\n";for(const auto &chart:charts){if(chart.mode=="grid"){const auto rows=chart.field["grid"].toArray();for(int y=0;y<rows.size();++y){const auto row=rows[y].toArray();for(int x=0;x<row.size();++x)stream<<quote(chart.title)<<",grid,"<<quote(QString::number(y)+":"+QString::number(x))<<','<<(row[x].isDouble()?QString::number(row[x].toDouble(),'g',12):QString())<<','<<quote(chart.unit)<<','<<quote(chart.source)<<','<<quote(chart.note)<<'\n';}}else for(const auto &s:chart.series)for(int i=0;i<s.values.size();++i)stream<<quote(chart.title)<<','<<quote(s.label)<<','<<quote(chart.labels.value(i))<<','<<(std::isfinite(s.values[i])?QString::number(s.values[i],'g',12):QString())<<','<<quote(chart.unit)<<','<<quote(chart.source)<<','<<quote(chart.note)<<'\n';}stream.flush();return out.commit();}
};
}
AnalysisDialog::AnalysisDialog(const ga::Project &project,bool english,QWidget *parent,bool darkTheme):QDialog(parent){setObjectName("analysis-workspace");setWindowTitle(bilingual(english,"Phân tích khu đất — GroundAtlas","Site analysis — GroundAtlas"));resize(1120,800);setMinimumSize(850,650);auto layout=new QVBoxLayout(this);layout->setContentsMargins(0,0,0,0);layout->addWidget(new Workspace(project,english,darkTheme,this));}
void AnalysisDialog::validateExports(const QString &directory){QDir dir(directory);dir.mkpath(".");auto workspace=static_cast<Workspace*>(layout()->itemAt(0)->widget());workspace->pdf(dir.filePath("analysis.pdf"));workspace->csv(dir.filePath("analysis.csv"));for(int i=0;i<workspace->charts.size();++i){workspace->canvas->chart=workspace->charts[i];workspace->png(dir.filePath(QString("chart-%1.png").arg(i,2,10,QChar('0'))));}workspace->canvas->chart=workspace->charts.first();}
